using System.Diagnostics;using System.IO;using System.Text;using DiscUtils;using DiscUtils.Fat;using DiscUtils.Ntfs;using DiscUtils.Partitions;using DiscUtils.Streams;using DiscUtils.Vhd;using DiscUtils.Vhdx;namespace DeviceLayoutToVhd;public enum VhdFormat{    Vhd,    Vhdx}public static class VhdCreator{    public static string CreateSingleDisk(DeviceLayoutInfo layout, string outputPath, VhdFormat format)    {        var physicalStore = layout.Stores.FirstOrDefault();        if (physicalStore == null && layout.StoragePools.Count > 0)        {            physicalStore = layout.StoragePools.FirstOrDefault()?.Stores.FirstOrDefault();        }        if (physicalStore == null)        {            Console.WriteLine("ERROR: No Store found in DeviceLayout XML");            return "";        }        var sectorSize = layout.SectorSize > 0 ? layout.SectorSize : 512;        var diskSize = physicalStore.SizeInSectors * sectorSize;        if (diskSize <= 0) diskSize = 32L * 1024 * 1024 * 1024;        if (File.Exists(outputPath))            File.Delete(outputPath);        Console.WriteLine($"  Creating {format} disk: {Path.GetFileName(outputPath)} ({diskSize / 1024.0 / 1024.0 / 1024.0:F2} GB)");        using var fs = new FileStream(outputPath, FileMode.Create, FileAccess.ReadWrite);        VirtualDisk disk;        if (format == VhdFormat.Vhdx)        {            disk = DiscUtils.Vhdx.Disk.InitializeDynamic(fs, Ownership.Dispose, diskSize);        }        else        {            disk = DiscUtils.Vhd.Disk.InitializeDynamic(fs, Ownership.Dispose, diskSize);        }        var actualSectorSize = disk.SectorSize > 0 ? disk.SectorSize : sectorSize;        var gpt = GuidPartitionTable.Initialize(disk);        long currentOffset = 1024 * 1024;        var partitions = physicalStore.Partitions.Where(p => p.TotalSectors > 0 || p.UseAllSpace).ToList();        var fixedPartitions = partitions.Where(p => !p.UseAllSpace && p.TotalSectors > 0).ToList();        var useAllPartitions = partitions.Where(p => p.UseAllSpace).ToList();        long fixedTotal = fixedPartitions.Sum(p => AlignTo(p.TotalSectors * actualSectorSize, layout.DefaultPartitionByteAlignment > 0 ? layout.DefaultPartitionByteAlignment : 0x200000));        long availableSpace = disk.Capacity - currentOffset - (1024 * 1024);        long spacePerUseAll = useAllPartitions.Count > 0 ? Math.Max(0, (availableSpace - fixedTotal) / useAllPartitions.Count) : 0;        int partIndex = 0;        foreach (var part in partitions)        {            partIndex++;            long partSize;            if (part.UseAllSpace && useAllPartitions.Count > 0)            {                partSize = spacePerUseAll;            }            else if (part.TotalSectors > 0)            {                partSize = part.TotalSectors * actualSectorSize;            }            else            {                Console.WriteLine($"    Skipping partition '{part.Name}' (no size)");                continue;            }            if (part.ByteAlignment > 0)                currentOffset = AlignTo(currentOffset, part.ByteAlignment);            else if (layout.DefaultPartitionByteAlignment > 0)                currentOffset = AlignTo(currentOffset, layout.DefaultPartitionByteAlignment);            if (currentOffset + partSize > disk.Capacity - (1024 * 1024))            {                partSize = disk.Capacity - (1024 * 1024) - currentOffset;                if (partSize <= 0)                {                    Console.WriteLine($"    Skipping partition '{part.Name}' (no space)");                    continue;                }            }            var partType = ParseGuid(part.Type);            if (partType == Guid.Empty)                partType = GuidPartitionTypes.WindowsBasicData;            var firstSector = currentOffset / actualSectorSize;            var lastSector = firstSector + (partSize / actualSectorSize) - 1;            Console.WriteLine($"    Partition {partIndex}: '{part.Name}' type={partType} LBA {firstSector}-{lastSector} size={partSize / 1024.0 / 1024.0:F1} MB fs={part.FileSystem}");            var partId = string.IsNullOrEmpty(part.Id) ? Guid.NewGuid() : ParseGuid(part.Id);            long attributes = part.Bootable ? 0x4 : 0;            gpt.Create(firstSector, lastSector, partType, attributes, part.Name);            var partitionIndex = gpt.Partitions.Count - 1;            if (!string.IsNullOrEmpty(part.FileSystem) && partSize > 1024 * 1024)            {                try                {                    if (part.FileSystem.Equals("NTFS", StringComparison.OrdinalIgnoreCase))                    {                        var partInfo = gpt.Partitions[partitionIndex];                        if (partInfo != null)                        {                            using var partStream = partInfo.Open();                            partStream.Position = 0;                            var clusterSize = part.ClusterSize > 0 ? part.ClusterSize : 4096;                            var geometry = disk.Geometry ?? new Geometry(disk.Capacity, 255, 63, actualSectorSize);                            NtfsFileSystem.Format(partStream, part.Name, geometry, partSize, clusterSize);                            Console.WriteLine($"      Formatted as NTFS");                        }                    }                    else if (part.FileSystem.Equals("FAT", StringComparison.OrdinalIgnoreCase) ||                             part.FileSystem.Equals("FAT32", StringComparison.OrdinalIgnoreCase))                    {                        FatFileSystem.FormatPartition(disk, partitionIndex, part.Name);                        Console.WriteLine($"      Formatted as FAT");                    }                }                catch (Exception ex)                {                    Console.WriteLine($"      Format failed: {ex.Message}");                }            }            currentOffset = (lastSector + 1) * actualSectorSize;        }        disk.Dispose();        Console.WriteLine($"  Done: {outputPath}");        return outputPath;    }    public static List<string> CreateStoragePoolDisks(DeviceLayoutInfo layout, string outputDir, VhdFormat format)    {        var results = new List<string>();        if (layout.StoragePools.Count == 0)        {            Console.WriteLine("ERROR: No StoragePool found in DeviceLayout XML");            return results;        }        Directory.CreateDirectory(outputDir);        var sectorSize = layout.SectorSize > 0 ? layout.SectorSize : 512;        foreach (var pool in layout.StoragePools)        {            Console.WriteLine($"  Storage Pool: {pool.Name} ({pool.Stores.Count} stores)");            foreach (var store in pool.Stores)            {                var storeName = !string.IsNullOrEmpty(store.StoreType) ? store.StoreType : store.Id;                var ext = format == VhdFormat.Vhdx ? "vhdx" : "vhd";                var outputPath = Path.Combine(outputDir, $"{storeName}.{ext}");                var diskSize = store.SizeInSectors * sectorSize;                if (diskSize <= 0) diskSize = 32L * 1024 * 1024 * 1024;                if (File.Exists(outputPath))                    File.Delete(outputPath);                Console.WriteLine($"    Creating {storeName}.{ext} ({diskSize / 1024.0 / 1024.0 / 1024.0:F2} GB)");                try                {                    using var fs = new FileStream(outputPath, FileMode.Create, FileAccess.ReadWrite);                    VirtualDisk disk;                    if (format == VhdFormat.Vhdx)                        disk = DiscUtils.Vhdx.Disk.InitializeDynamic(fs, Ownership.Dispose, diskSize);                    else                        disk = DiscUtils.Vhd.Disk.InitializeDynamic(fs, Ownership.Dispose, diskSize);                    var actualSectorSize = disk.SectorSize > 0 ? disk.SectorSize : sectorSize;                    var gpt = GuidPartitionTable.Initialize(disk);                    long currentOffset = 1024 * 1024;                    var partitions = store.Partitions.Where(p => p.TotalSectors > 0 || p.UseAllSpace).ToList();                    var fixedPartitions = partitions.Where(p => !p.UseAllSpace && p.TotalSectors > 0).ToList();                    var useAllPartitions = partitions.Where(p => p.UseAllSpace).ToList();                    long fixedTotal = fixedPartitions.Sum(p => AlignTo(p.TotalSectors * actualSectorSize, 0x200000));                    long availableSpace = disk.Capacity - currentOffset - (1024 * 1024);                    long spacePerUseAll = useAllPartitions.Count > 0 ? Math.Max(0, (availableSpace - fixedTotal) / useAllPartitions.Count) : 0;                    int partIndex = 0;                    foreach (var part in partitions)                    {                        partIndex++;                        long partSize;                        if (part.UseAllSpace && useAllPartitions.Count > 0)                            partSize = spacePerUseAll;                        else if (part.TotalSectors > 0)                            partSize = part.TotalSectors * actualSectorSize;                        else                            continue;                        if (part.ByteAlignment > 0)                            currentOffset = AlignTo(currentOffset, part.ByteAlignment);                        else                            currentOffset = AlignTo(currentOffset, 0x200000);                        if (currentOffset + partSize > disk.Capacity - (1024 * 1024))                            partSize = disk.Capacity - (1024 * 1024) - currentOffset;                        if (partSize <= 0) continue;                        var partType = ParseGuid(part.Type);                        if (partType == Guid.Empty) partType = GuidPartitionTypes.WindowsBasicData;                        var firstSector = currentOffset / actualSectorSize;                        var lastSector = firstSector + (partSize / actualSectorSize) - 1;                        Console.WriteLine($"      Partition {partIndex}: '{part.Name}' size={partSize / 1024.0 / 1024.0:F1} MB fs={part.FileSystem}");                        gpt.Create(firstSector, lastSector, partType, part.Bootable ? 0x4L : 0, part.Name);                        var partitionIndex = gpt.Partitions.Count - 1;                        if (!string.IsNullOrEmpty(part.FileSystem) && partSize > 1024 * 1024)                        {                            try                            {                                if (part.FileSystem.Equals("NTFS", StringComparison.OrdinalIgnoreCase))                                {                                    using var ps = gpt.Partitions[partitionIndex].Open();                                    ps.Position = 0;                                    var clusterSize = part.ClusterSize > 0 ? part.ClusterSize : 4096;                                    var geo = disk.Geometry ?? new Geometry(disk.Capacity, 255, 63, actualSectorSize);                                    NtfsFileSystem.Format(ps, part.Name, geo, partSize, clusterSize);                                }                                else if (part.FileSystem.StartsWith("FAT", StringComparison.OrdinalIgnoreCase))                                {                                    FatFileSystem.FormatPartition(disk, partitionIndex, part.Name);                                }                            }                            catch (Exception fex)                            {                                Console.WriteLine($"        Format failed: {fex.Message}");                            }                        }                        currentOffset = (lastSector + 1) * actualSectorSize;                    }                    disk.Dispose();                    results.Add(outputPath);                    Console.WriteLine($"    Done: {storeName}.{ext}");                }                catch (Exception ex)                {                    Console.WriteLine($"    Failed to create {storeName}: {ex.Message}");                }            }        }        Console.WriteLine($"  Storage pool disks created: {results.Count}");        return results;    }    public static string CreateStoragePoolMemberDisk(string outputPath, long diskSizeBytes, VhdFormat format)    {        if (File.Exists(outputPath))            File.Delete(outputPath);        Console.WriteLine($"  Creating storage pool member disk: {Path.GetFileName(outputPath)} ({diskSizeBytes / 1024.0 / 1024.0 / 1024.0:F2} GB)");        bool useHyperV = false;        try        {            var checkPsi = new ProcessStartInfo            {                FileName = "powershell.exe",                Arguments = "-NoProfile -Command \"Get-Command New-VHD -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Name\"",                UseShellExecute = false,                RedirectStandardOutput = true,                CreateNoWindow = true            };            var checkProc = Process.Start(checkPsi);            var checkOutput = checkProc?.StandardOutput.ReadToEnd();            checkProc?.WaitForExit(5000);            useHyperV = !string.IsNullOrEmpty(checkOutput) && checkOutput.Contains("New-VHD");        }        catch { useHyperV = false; }        if (useHyperV)        {            Console.WriteLine("  Using Hyper-V New-VHD...");            var vhdType = format == VhdFormat.Vhdx ? "vhdx" : "vhd";            var psi = new ProcessStartInfo            {                FileName = "powershell.exe",                Arguments = $"-NoProfile -Command \"New-VHD -Path '{outputPath}' -SizeBytes {diskSizeBytes} -Dynamic -ErrorAction Stop\"",                UseShellExecute = false,                RedirectStandardOutput = true,                RedirectStandardError = true,                CreateNoWindow = true            };            var proc = Process.Start(psi);            proc?.WaitForExit(60000);            if (proc != null && proc.ExitCode == 0 && File.Exists(outputPath))            {                Console.WriteLine($"  Done (Hyper-V): {outputPath}");                return outputPath;            }            Console.WriteLine("  Hyper-V New-VHD failed, falling back to DiscUtils...");            if (File.Exists(outputPath)) File.Delete(outputPath);        }        var fs = new FileStream(outputPath, FileMode.Create, FileAccess.ReadWrite, FileShare.None);        VirtualDisk disk;        if (format == VhdFormat.Vhdx)            disk = DiscUtils.Vhdx.Disk.InitializeDynamic(fs, Ownership.Dispose, diskSizeBytes);        else            disk = DiscUtils.Vhd.Disk.InitializeDynamic(fs, Ownership.Dispose, diskSizeBytes);        disk.Dispose();        Console.WriteLine($"  Done (DiscUtils): {outputPath}");        return outputPath;    }    public static string GenerateStoragePoolScript(DeviceLayoutInfo layout, string vhdPath, string scriptPath)
    {
        if (layout.StoragePools.Count == 0)
        {
            Console.WriteLine("ERROR: No StoragePool found");
            return "";
        }

        var pool = layout.StoragePools[0];
        var poolName = string.IsNullOrEmpty(pool.Name) ? "OSPool" : pool.Name;
        var sectorSize = layout.SectorSize > 0 ? layout.SectorSize : 512;

        long vhdSize = 0;
        var topStore = layout.Stores.FirstOrDefault();
        if (topStore != null && topStore.SizeInSectors > 0)
        {
            vhdSize = topStore.SizeInSectors * sectorSize;
        }
        else
        {
            long maxStoreSize = 0;
            foreach (var store in pool.Stores)
            {
                var sz = store.SizeInSectors * sectorSize;
                if (sz > maxStoreSize) maxStoreSize = sz;
            }
            vhdSize = maxStoreSize;
        }

        if (vhdSize <= 0)
        {
            Console.WriteLine("  WARNING: No valid size found, using default 4GB");
            vhdSize = 4L * 1024 * 1024 * 1024;
        }

        if (vhdSize < 1L * 1024 * 1024 * 1024) vhdSize = 1L * 1024 * 1024 * 1024;
        vhdSize = (vhdSize / (1024 * 1024)) * (1024 * 1024);

        Console.WriteLine($"  VHD size: {vhdSize} bytes ({vhdSize / 1024.0 / 1024 / 1024:F2} GB)");

        var vhdExt = Path.GetExtension(vhdPath).ToLowerInvariant();
        var isVhdx = vhdExt == ".vhdx";
        const string ospoolGuid = "5708A6E0-9001-4b99-b064-1fe564896bdb";

        var sb = new System.Text.StringBuilder();
        sb.AppendLine("#Requires -RunAsAdministrator");
        sb.AppendLine("$ErrorActionPreference = 'Continue'");
        sb.AppendLine("");
        sb.AppendLine($"$vhdPath = '{vhdPath}'");
        sb.AppendLine($"$poolName = '{poolName}'");
        sb.AppendLine($"$vhdSize = {vhdSize}");
        sb.AppendLine("");
        sb.AppendLine("Write-Host '=== Dismount existing VHD if mounted ===' -ForegroundColor Cyan");
        sb.AppendLine("try { Dismount-VHD -Path $vhdPath -ErrorAction SilentlyContinue; Start-Sleep -Seconds 1 } catch {}");
        sb.AppendLine("");
        sb.AppendLine("Write-Host '=== Creating VHD ===' -ForegroundColor Cyan");
        sb.AppendLine("if (Test-Path $vhdPath) { Remove-Item $vhdPath -Force }");
        if (isVhdx)
            sb.AppendLine("New-VHD -Path $vhdPath -SizeBytes $vhdSize -Dynamic | Out-Null");
        else
            sb.AppendLine("New-VHD -Path $vhdPath -SizeBytes $vhdSize -Dynamic -VHDFormat VHD | Out-Null");
        sb.AppendLine("Write-Host 'VHD created.' -ForegroundColor Green");
        sb.AppendLine("");
        sb.AppendLine("Write-Host '=== Mounting VHD ===' -ForegroundColor Cyan");
        sb.AppendLine("Mount-VHD -Path $vhdPath -PassThru | Out-Null");
        sb.AppendLine("Start-Sleep -Seconds 2");
        sb.AppendLine("$disk = Get-Disk | Where-Object { $_.Location -eq $vhdPath } | Select-Object -First 1");
        sb.AppendLine("if (-not $disk) { Write-Host 'ERROR: VHD disk not found' -ForegroundColor Red; exit 1 }");
        sb.AppendLine("Write-Host \"Found disk: $($disk.Number)\"");
        sb.AppendLine("");
        sb.AppendLine("Write-Host '=== Initializing disk ===' -ForegroundColor Cyan");
        sb.AppendLine("Set-Disk -Number $disk.Number -IsOffline $false");
        sb.AppendLine("Set-Disk -Number $disk.Number -IsReadOnly $false");
        sb.AppendLine("Initialize-Disk -Number $disk.Number -PartitionStyle GPT -Confirm:$false");
        sb.AppendLine("Write-Host 'Disk initialized as GPT.'");
        sb.AppendLine("");

        if (topStore != null)
        {
            sb.AppendLine("Write-Host '=== Creating top-level partitions ===' -ForegroundColor Cyan");
            int pIdx = 0;
            foreach (var part in topStore.Partitions)
            {
                pIdx++;
                var partName = string.IsNullOrEmpty(part.Name) ? $"Partition{pIdx}" : part.Name;
                var partType = string.IsNullOrEmpty(part.Type) ? "ebd0a0a2-b9e5-4433-87c0-68b6b72699c7" : part.Type.Trim('{', '}');
                var isOspool = partType.Equals(ospoolGuid, StringComparison.OrdinalIgnoreCase);

                if (isOspool)
                {
                    sb.AppendLine("# OSPool partition (uses remaining space)");
                    sb.AppendLine("Write-Host 'Creating OSPool partition...'");
                    sb.AppendLine($"$ospoolPart = New-Partition -DiskNumber $disk.Number -UseMaximumSize");
                    sb.AppendLine($"Set-Partition -DiskNumber $disk.Number -PartitionNumber $ospoolPart.PartitionNumber -GptType '{{{ospoolGuid}}}'");
                    sb.AppendLine("Write-Host 'OSPool partition created.'");
                    sb.AppendLine("");
                }
                else
                {
                    var partSize = part.TotalSectors * sectorSize;
                    if (part.UseAllSpace || partSize <= 0)
                    {
                        sb.AppendLine($"# Partition {pIdx}: {partName} (UseAllSpace)");
                        sb.AppendLine($"$p = New-Partition -DiskNumber $disk.Number -UseMaximumSize");
                    }
                    else
                    {
                        sb.AppendLine($"# Partition {pIdx}: {partName} ({partSize / 1024.0 / 1024.0:F1} MB)");
                        sb.AppendLine($"$p = New-Partition -DiskNumber $disk.Number -Size {partSize}");
                    }
                    sb.AppendLine($"Set-Partition -DiskNumber $disk.Number -PartitionNumber $p.PartitionNumber -GptType '{{{partType}}}'");
                    sb.AppendLine("Start-Sleep -Milliseconds 100");
                    sb.AppendLine("");
                }
            }
        }

        sb.AppendLine("Write-Host '=== Top-level partitions created ===' -ForegroundColor Green");
        sb.AppendLine("");
        sb.AppendLine("Write-Host '=== Partition layout ===' -ForegroundColor Cyan");
        sb.AppendLine("Get-Partition -DiskNumber $disk.Number | Select-Object PartitionNumber, Type, Size, Offset | Format-Table -AutoSize");
        sb.AppendLine("");
        sb.AppendLine("Write-Host 'Script complete. The main program will now create the storage pool using native API.' -ForegroundColor Yellow");
        sb.AppendLine("# Script complete, exiting...");
        

        File.WriteAllText(scriptPath, sb.ToString(), System.Text.Encoding.UTF8);
        Console.WriteLine($"  Script generated: {scriptPath}");
        return scriptPath;
    }
    public static string CreateWSKStoragePoolVhd(DeviceLayoutInfo layout, string outputPath, VhdFormat format)    {        var sectorSize = layout.SectorSize > 0 ? layout.SectorSize : 4096;        var pool = layout.StoragePools.FirstOrDefault();        if (pool == null)        {            Console.WriteLine("ERROR: No StoragePool found in layout");            return "";        }        long totalPoolSize = 0;        foreach (var store in pool.Stores)        {            var sz = store.SizeInSectors * sectorSize;            if (sz <= 0) sz = 2L * 1024 * 1024 * 1024;            totalPoolSize += sz;        }        totalPoolSize = (long)(totalPoolSize * 1.15);        long oppSize = 8192 * sectorSize;        long efiSize = 8192 * sectorSize;        long reservedSize = 1024 * 1024;        long diskSize = oppSize + efiSize + totalPoolSize + reservedSize * 4;        if (diskSize < 32L * 1024 * 1024 * 1024) diskSize = 32L * 1024 * 1024 * 1024;        if (File.Exists(outputPath))            File.Delete(outputPath);        Console.WriteLine($"  Creating WSK Storage Pool {format} disk: {Path.GetFileName(outputPath)}");        Console.WriteLine($"    Sector size: {sectorSize}");        Console.WriteLine($"    Disk size: {diskSize / 1024.0 / 1024.0 / 1024.0:F2} GB");        Console.WriteLine($"    Storage pool: {pool.Name} ({pool.Stores.Count} virtual disks)");        using var fs = new FileStream(outputPath, FileMode.Create, FileAccess.ReadWrite);        VirtualDisk disk;        if (format == VhdFormat.Vhdx)            disk = DiscUtils.Vhdx.Disk.InitializeDynamic(fs, Ownership.Dispose, diskSize);        else            disk = DiscUtils.Vhd.Disk.InitializeDynamic(fs, Ownership.Dispose, diskSize);        var actualSectorSize = disk.SectorSize > 0 ? disk.SectorSize : sectorSize;        var gpt = GuidPartitionTable.Initialize(disk);        long currentOffset = 1024 * 1024;        var alignment = layout.DefaultPartitionByteAlignment > 0 ? layout.DefaultPartitionByteAlignment : 0x200000;        var oppType = new Guid("ebd0a0a2-b9e5-4433-87c0-68b6b72699c7");        var efiType = new Guid("c12a7328-f81f-11d2-ba4b-00a0c93ec93b");        var poolType = new Guid("5708a6e0-9001-4b99-b064-1fe564896bdb");        currentOffset = AlignTo(currentOffset, alignment);        var oppFirst = currentOffset / actualSectorSize;        var oppLast = oppFirst + (oppSize / actualSectorSize) - 1;        gpt.Create(oppFirst, oppLast, oppType, 0, "OPP");        Console.WriteLine($"    Partition: OPP LBA {oppFirst}-{oppLast}");        currentOffset = (oppLast + 1) * actualSectorSize;        currentOffset = AlignTo(currentOffset, alignment);        var efiFirst = currentOffset / actualSectorSize;        var efiLast = efiFirst + (efiSize / actualSectorSize) - 1;        gpt.Create(efiFirst, efiLast, efiType, 0, "BS_EFIESP");        var efiPartIdx = gpt.Partitions.Count - 1;        Console.WriteLine($"    Partition: BS_EFIESP LBA {efiFirst}-{efiLast}");        try        {            FatFileSystem.FormatPartition(disk, efiPartIdx, "BS_EFIESP");            Console.WriteLine("      Formatted as FAT");        }        catch (Exception fex)        {            Console.WriteLine($"      FAT format failed: {fex.Message}");        }        currentOffset = (efiLast + 1) * actualSectorSize;        currentOffset = AlignTo(currentOffset, alignment);        var poolFirst = currentOffset / actualSectorSize;        var poolLast = (disk.Capacity - (1024 * 1024)) / actualSectorSize - 1;        gpt.Create(poolFirst, poolLast, poolType, 0, "OSPool");        Console.WriteLine($"    Partition: OSPool LBA {poolFirst}-{poolLast} (Storage Spaces member)");        disk.Dispose();        Console.WriteLine($"  Done: {outputPath}");        return outputPath;    }    public static string GenerateWSKStoragePoolScript(DeviceLayoutInfo layout, string vhdPath, string scriptPath)    {        var pool = layout.StoragePools.FirstOrDefault();        if (pool == null) return "";        var sectorSize = layout.SectorSize > 0 ? layout.SectorSize : 4096;        var sb = new System.Text.StringBuilder();        sb.AppendLine("#Requires -RunAsAdministrator");        sb.AppendLine("# WSK Storage Pool Creation Script");        sb.AppendLine("# Generated by DeviceLayout_Exchanger (WSK Tools)");        sb.AppendLine("");        sb.AppendLine("$ErrorActionPreference = 'Continue'");        sb.AppendLine("");        sb.AppendLine($"$vhdPath = '{vhdPath}'");        sb.AppendLine($"$poolName = '{pool.Name}'");        sb.AppendLine("");        sb.AppendLine("Write-Host '=== Mounting VHD ===' -ForegroundColor Cyan");        sb.AppendLine("Mount-VHD -Path $vhdPath -PassThru | Out-Null");        sb.AppendLine("Start-Sleep -Seconds 2");        sb.AppendLine("");        sb.AppendLine("$disk = Get-Disk | Where-Object { $_.Location -eq $vhdPath } | Select-Object -First 1");        sb.AppendLine("if (-not $disk) { Write-Host 'ERROR: VHD disk not found' -ForegroundColor Red; exit 1 }");        sb.AppendLine("Write-Host \"Found disk: $($disk.Number) ($($disk.FriendlyName))\"");        sb.AppendLine("");        sb.AppendLine("$poolPartition = Get-Partition -DiskNumber $disk.Number | Where-Object { $_.Type -eq '5708a6e0-9001-4b99-b064-1fe564896bdb' } | Select-Object -First 1");        sb.AppendLine("if (-not $poolPartition) {");        sb.AppendLine("    $poolPartition = Get-Partition -DiskNumber $disk.Number | Where-Object { $_.GptType -eq '{5708a6e0-9001-4b99-b064-1fe564896bdb}' } | Select-Object -First 1");        sb.AppendLine("}");        sb.AppendLine("if (-not $poolPartition) { Write-Host 'ERROR: OSPool partition not found' -ForegroundColor Red; exit 1 }");        sb.AppendLine("Write-Host \"OSPool partition: $($poolPartition.PartitionNumber)\"");        sb.AppendLine("");        sb.AppendLine("Write-Host '=== Initializing OSPool partition as storage pool member ===' -ForegroundColor Cyan");        sb.AppendLine("$beforePhysicalDisks = Get-PhysicalDisk | Select-Object -ExpandProperty UniqueId");        sb.AppendLine("Start-Sleep -Milliseconds 500");        sb.AppendLine("$allPhysicalDisks = Get-PhysicalDisk");        sb.AppendLine("$physicalDisk = $allPhysicalDisks | Where-Object { $beforePhysicalDisks -notcontains $_.UniqueId } | Select-Object -First 1");        sb.AppendLine("if (-not $physicalDisk) {");        sb.AppendLine("    Write-Host 'WARNING: Cannot find new physical disk, trying DeviceId match...' -ForegroundColor Yellow");        sb.AppendLine("    $physicalDisk = $allPhysicalDisks | Where-Object { $_.DeviceId -eq $disk.Number } | Select-Object -First 1");        sb.AppendLine("}");        sb.AppendLine("if (-not $physicalDisk) {");        sb.AppendLine("    Write-Host 'WARNING: Trying BusType FileBackedVirtual...' -ForegroundColor Yellow");        sb.AppendLine("    $physicalDisk = $allPhysicalDisks | Where-Object { $_.BusType -eq 'FileBackedVirtual' } | Select-Object -First 1");        sb.AppendLine("}");        sb.AppendLine("if (-not $physicalDisk) { Write-Host 'ERROR: Physical disk not found' -ForegroundColor Red; exit 1 }");        sb.AppendLine("Write-Host \"Physical disk: $($physicalDisk.FriendlyName) (DeviceId=$($physicalDisk.DeviceId), BusType=$($physicalDisk.BusType))\"");        sb.AppendLine("");        sb.AppendLine("Write-Host '=== Creating storage pool ===' -ForegroundColor Cyan");        sb.AppendLine("$existingPool = Get-StoragePool -FriendlyName $poolName -ErrorAction SilentlyContinue");        sb.AppendLine("if ($existingPool) {");        sb.AppendLine("    Write-Host \"Storage pool '$poolName' already exists, removing...\" -ForegroundColor Yellow");        sb.AppendLine("    Remove-StoragePool -FriendlyName $poolName -Confirm:$false");        sb.AppendLine("}");        sb.AppendLine("$pool = New-StoragePool -FriendlyName $poolName -StorageSubSystemFriendlyName '*Storage Spaces*' -PhysicalDisks $physicalDisk -ProvisioningTypeDefault Fixed -ResiliencySettingNameDefault Simple");        sb.AppendLine("Write-Host \"Storage pool created: $($pool.FriendlyName)\"");        sb.AppendLine("");        int vdIdx = 0;        foreach (var store in pool.Stores)        {            vdIdx++;            var vdName = !string.IsNullOrEmpty(store.StoreType) ? store.StoreType : $"VirtualDisk{vdIdx}";            var vdSize = store.SizeInSectors * sectorSize;            if (vdSize <= 0) vdSize = 2L * 1024 * 1024 * 1024;            sb.AppendLine($"Write-Host '=== Creating virtual disk: {vdName} ({vdSize / 1024.0 / 1024.0 / 1024.0:F2} GB) ===' -ForegroundColor Cyan");            sb.AppendLine($"$vd = New-VirtualDisk -StoragePoolFriendlyName $poolName -FriendlyName '{vdName}' -Size {vdSize} -ProvisioningType Thin -ResiliencySettingName Simple -NumberOfColumns 1 -PhysicalDiskRedundancy 0");            sb.AppendLine("$vdDisk = Get-Disk -VirtualDisk $vd");            sb.AppendLine("Initialize-Disk -Number $vdDisk.Number -PartitionStyle GPT -Confirm:$false");            sb.AppendLine("Start-Sleep -Milliseconds 500");            sb.AppendLine("");            int partIdx = 0;            foreach (var part in store.Partitions)            {                partIdx++;                var partName = string.IsNullOrEmpty(part.Name) ? $"Partition{partIdx}" : part.Name;                var partType = string.IsNullOrEmpty(part.Type) ? "ebd0a0a2-b9e5-4433-87c0-68b6b72699c7" : part.Type.Trim('{', '}');                var partSize = part.TotalSectors * sectorSize;                sb.AppendLine($"# Partition: {partName}");                if (part.UseAllSpace || partSize <= 0)                {                    sb.AppendLine($"$p = New-Partition -DiskNumber $vdDisk.Number -UseMaximumSize -GptType '{{{partType}}}'");                }                else                {                    sb.AppendLine($"$p = New-Partition -DiskNumber $vdDisk.Number -Size {partSize} -GptType '{{{partType}}}'");                }                if (!string.IsNullOrEmpty(part.FileSystem) && part.FileSystem.StartsWith("FAT", StringComparison.OrdinalIgnoreCase))                {                    sb.AppendLine($"Format-Volume -Partition $p -FileSystem FAT32 -NewFileSystemLabel '{partName}' -Confirm:$false -Force | Out-Null");                }                else if (!string.IsNullOrEmpty(part.FileSystem) && part.FileSystem.Equals("NTFS", StringComparison.OrdinalIgnoreCase))                {                    sb.AppendLine($"Format-Volume -Partition $p -FileSystem NTFS -NewFileSystemLabel '{partName}' -Confirm:$false -Force | Out-Null");                }                sb.AppendLine("");            }        }        sb.AppendLine("Write-Host ''");        sb.AppendLine("Write-Host '=== WSK Storage Pool creation complete! ===' -ForegroundColor Green");        sb.AppendLine("Write-Host 'Open Disk Management or Server Manager to view the storage pool.'");        sb.AppendLine("Write-Host ''");        sb.AppendLine("Get-VirtualDisk | Format-Table FriendlyName, Size, HealthStatus, OperationalStatus");        sb.AppendLine("Write-Host ''");        sb.AppendLine("# Script complete, exiting...");                File.WriteAllText(scriptPath, sb.ToString(), Encoding.UTF8);        Console.WriteLine($"  Script generated: {scriptPath}");        return scriptPath;    }    public static bool ExecuteStoragePoolScript(string scriptPath, out string output)    {        output = "";        try        {            string logPath = Path.Combine(Path.GetDirectoryName(scriptPath), "Create-StoragePool-Output.log");            string wrapperPath = Path.Combine(Path.GetDirectoryName(scriptPath), "Run-Elevated.ps1");            string wrapperContent = "$ErrorActionPreference = 'Continue'" + Environment.NewLine + "& '" + scriptPath + "' *> '" + logPath + "'" + Environment.NewLine + "$exitCode = $LASTEXITCODE" + Environment.NewLine + "exit $exitCode";            File.WriteAllText(wrapperPath, wrapperContent);            var psi = new ProcessStartInfo            {                FileName = "powershell.exe",                Arguments = $"-NoPro